set client_min_messages = warning;
create or replace function sb(v text) returns text language sql as $$ select coalesce(x->>'stockBy','(sin sedes)') || ' total=' || (x->>'stock') from store_data, jsonb_array_elements(data->'products') p, jsonb_array_elements(p->'variants') x where x->>'id' = v $$;
create or replace function gid(c text) returns bigint language sql as $$ select id from stock_transfers where code = c $$;
update store_data set data = jsonb_set(data, '{products,0,variants,1,stock}', '10');
insert into staff_profiles (user_id, username, name, role) values ('88888888-8888-8888-8888-888888888888','alm','Rosa Almacén','almacen');
select t_as('{"sub":"11111111-1111-1111-1111-111111111111","aal":"aal2"}');
select '1) Admin envía 6 Larco→Almacén ' || (create_transfer('principal','almacen','[{"variantId":"v2","qty":6}]','Guardar temporada')->>'code') || ' · en camino: ' || sb('v2');
select t_as('{"sub":"88888888-8888-8888-8888-888888888888","aal":"aal1"}');
select '2) Almacén recibe (' || (receive_transfer(gid('T001-000001'))->>'received_by') || '): ' || sb('v2');
select '3) ' || t_expect_error($q$ select create_transfer('almacen','principal','[{"variantId":"v2","qty":9}]') $q$, 'STOCK_INSUFICIENTE');
select '4) Almacén envía 3 a Larco ' || (create_transfer('almacen','principal','[{"variantId":"v2","qty":3}]','Reposición')->>'code') || ' · ' || sb('v2');
select t_as('{"sub":"22222222-2222-2222-2222-222222222222","aal":"aal1"}');
select '5) vendedora no anula: ' || t_expect_error($q$ select cancel_transfer(gid('T001-000002'),'x') $q$, 'SIN_PERMISO');
select '6) faltante pide motivo: ' || t_expect_error($q$ select receive_transfer(gid('T001-000002'), '{"v2":2}') $q$, 'MOTIVO_FALTANTE');
select '7) vendedora Larco recibe 2 de 3: ' || (receive_transfer(gid('T001-000002'), '{"v2":2}', 'Una llegó con mancha')->>'received_by') || ' · ' || sb('v2');
select '8) ' || t_expect_error($q$ select receive_transfer(gid('T001-000002')) $q$, 'GUIA_YA_CERRADA');
select t_as('{"sub":"88888888-8888-8888-8888-888888888888","aal":"aal1"}');
select '9) envía 1 ' || (create_transfer('almacen','principal','[{"variantId":"v2","qty":1}]')->>'code') || ' · ' || sb('v2');
select '10) anula: ' || (cancel_transfer(gid('T001-000003'),'Me equivoqué de talla')->>'status') || ' · ' || sb('v2');
set role anon; select '11) web: ' || t_expect_error('select count(*) from stock_transfers','permission'); reset role;
select code, status, created_by, received_by, items->0->>'qty' q, items->0->>'received' rec, receive_note, void_reason from stock_transfers order by id;
select type, qty, stock_before, stock_after, store_id, doc from stock_movements where variant_id='v2' order by id;
